        label: "Cyberpunk",
        bg: "#030010",
        surface: "#08001F",
        card: "#0E0030",
        accent: "#00FFFF",
        accent2: "#7C3AED",
        text: "#E0CFFF",
        textMuted: "rgba(224,207,255,0.45)",
        border: "rgba(0,255,255,0.18)",
        borderH: "rgba(0,255,255,0.45)",
        orb1: "#7C3AED",
        orb2: "#00FFFF",
        pos: "#00FF88",
        neg: "#FF4488",
        purp: "#BF5FFF",
        navBg: "rgba(3,0,16,0.9)"
    },
    moonlight: {
        id: "moonlight",
        label: "Moonlight",
        bg: "#060A14",
        surface: "#0D1426",
        card: "#131D35",
        accent: "#94A3B8",
