const StatCard = ({ T, icon, label, value, sub, color, delay, isLight }) => {
  const [vis, setVis] = useState(false);
  useEffect(() => { const t = setTimeout(() => setVis(true), delay); return () => clearTimeout(t); }, [delay]);
  return (
    <div className="card-hover" style={{
      background: T.card, border: `1px solid ${T.border}`, borderRadius: 20,
      padding: "24px 22px", position: "relative", overflow: "hidden",
      opacity: vis ? 1 : 0, transform: vis ? "translateY(0)" : "translateY(20px)",
      transition: `all 0.6s cubic-bezier(0.16,1,0.3,1) ${delay}ms`,
      boxShadow: isLight ? "0 4px 20px rgba(0,0,0,0.06)" : "none",
    }}>
      <div style={{ position: "absolute", top: -20, right: -20, width: 80, height: 80, borderRadius: "50%", background: color, opacity: 0.08, filter: "blur(20px)" }} />
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 14 }}>
        <div style={{ fontSize: "1.4rem" }}>{icon}</div>
        <div style={{ fontSize: "0.7rem", color: sub?.startsWith("+") ? T.pos : T.neg, fontWeight: 700, background: sub?.startsWith("+") ? `${T.pos}18` : `${T.neg}18`, padding: "3px 9px", borderRadius: 20 }}>{sub}</div>
      </div>
      <div style={{ fontSize: "0.75rem", color: T.textMuted, fontWeight: 600, marginBottom: 6, textTransform: "uppercase", letterSpacing: 1 }}>{label}</div>
      <div style={{ fontSize: "1.7rem", fontFamily: "'Playfair Display',serif", fontWeight: 900, color: color }}>{value}</div>
    </div>
  );
};

const MiniBarChart = ({ T, data, isLight }) => {
  const maxVal = Math.max(...data.flatMap(d => [d.inc, d.exp]));
  const [anim, setAnim] = useState(false);
  useEffect(() => { setTimeout(() => setAnim(true), 300); }, []);
  return (
    <div style={{ display: "flex", gap: 10, alignItems: "flex-end", height: 120 }}>
      {data.map((d, i) => (
        <div key={i} style={{ flex: 1, display: "flex", gap: 3, alignItems: "flex-end" }}>
          <div style={{
            flex: 1, borderRadius: "4px 4px 0 0", background: `${T.pos}`, opacity: 0.85,
            height: anim ? `${(d.inc / maxVal) * 100}%` : "0%",
            transition: `height 0.8s cubic-bezier(0.34,1.2,0.64,1) ${i * 80}ms`,
            minHeight: 2
          }} />
          <div style={{
            flex: 1, borderRadius: "4px 4px 0 0", background: T.neg, opacity: 0.85,
            height: anim ? `${(d.exp / maxVal) * 100}%` : "0%",
            transition: `height 0.8s cubic-bezier(0.34,1.2,0.64,1) ${i * 80 + 40}ms`,
            minHeight: 2
          }} />
        </div>
      ))}
    </div>
  );
};

