  const filtered = filter === "all" ? installments : installments.filter(i => i.status === filter);
  const totalEMI = installments.filter(i => i.status === "active").reduce((s, i) => s + i.emi, 0);

  return (
    <div style={{ padding: "100px 28px 40px", maxWidth: 1300, margin: "0 auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 36 }}>
        <div>
          <div style={{ fontSize: "0.75rem", color: T.accent, fontWeight: 700, letterSpacing: 3, textTransform: "uppercase", marginBottom: 8 }}>Recurring Payments</div>
          <h1 style={{ fontFamily: "'Playfair Display',serif", fontSize: "clamp(1.8rem,3vw,2.6rem)", fontWeight: 900, color: T.text }}>
            Installments <span style={{ background: `linear-gradient(90deg,${T.accent},${T.accent2 || T.accent})`, WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent", backgroundClip: "text" }}>Manager</span>
          </h1>
        </div>
        <button onClick={() => setShowForm(true)} style={{
          padding: "12px 24px", borderRadius: 50, border: "none", cursor: "pointer",
          background: `linear-gradient(135deg,${T.accent},${T.orb1 || T.accent})`,
          color: isLight ? "#fff" : "#080612", fontWeight: 700, fontSize: "0.88rem",
          fontFamily: "'DM Sans',sans-serif", boxShadow: `0 8px 24px ${T.accent}40`,
          transition: "all 0.3s",
        }}>+ Add Installment</button>
      </div>

      {/* Summary Row */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12, marginBottom: 24 }}>
        {[
          { l: "Total EMI / Month", v: `₹${totalEMI.toLocaleString()}`, icon: "📅", c: T.neg },
          { l: "Active Loans", v: "4", icon: "🔄", c: T.accent },
          { l: "Completed", v: "1", icon: "✅", c: T.pos },
          { l: "Total Outstanding", v: "₹32.1L", icon: "💰", c: T.purp },
        ].map((s, i) => (
          <div key={i} className="card-hover" style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: "18px 16px", boxShadow: isLight ? "0 4px 20px rgba(0,0,0,0.06)" : "none" }}>
            <div style={{ fontSize: "1.2rem", marginBottom: 8 }}>{s.icon}</div>
            <div style={{ fontSize: "0.7rem", color: T.textMuted, fontWeight: 700, textTransform: "uppercase", letterSpacing: 1, marginBottom: 4 }}>{s.l}</div>
            <div style={{ fontFamily: "'Playfair Display',serif", fontSize: "1.3rem", fontWeight: 900, color: s.c }}>{s.v}</div>
          </div>
        ))}
      </div>

      {/* Filter */}
      <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
        {["all", "active", "complete"].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{
            padding: "8px 20px", borderRadius: 20, border: `1px solid ${filter === f ? T.accent : T.border}`,
            background: filter === f ? `${T.accent}18` : "transparent",
            color: filter === f ? T.accent : T.textMuted, fontWeight: 600, fontSize: "0.8rem",
            cursor: "pointer", fontFamily: "'DM Sans',sans-serif", textTransform: "capitalize", transition: "all 0.2s",
          }}>{f === "all" ? "All" : f.charAt(0).toUpperCase() + f.slice(1)}</button>
        ))}
      </div>

      {/* Cards */}
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {filtered.map((inst, i) => {
          const pct = Math.round((inst.paid / inst.total) * 100);
          return (
            <div key={inst.id} className="card-hover" style={{
              background: T.card, border: `1px solid ${T.border}`, borderRadius: 18, padding: "22px 24px",
              display: "flex", alignItems: "center", gap: 20,
              boxShadow: isLight ? "0 4px 20px rgba(0,0,0,0.06)" : "none",
              opacity: inst.status === "complete" ? 0.7 : 1,
              animation: `fadeInUp 0.5s cubic-bezier(0.16,1,0.3,1) ${i * 60}ms both`,
            }}>
              <div style={{ width: 50, height: 50, borderRadius: 16, background: `${inst.color}18`, border: `1px solid ${inst.color}40`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: "1.4rem", flexShrink: 0 }}>{inst.icon}</div>
              <div style={{ flex: 1 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                  <div>
                    <div style={{ fontSize: "0.95rem", fontWeight: 700, color: T.text }}>{inst.name}</div>
                    <div style={{ fontSize: "0.72rem", color: T.textMuted, marginTop: 2 }}>{inst.doneMonths}/{inst.months} months · Next due: {inst.nextDue}</div>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    {inst.status === "active" && <div style={{ fontFamily: "'Playfair Display',serif", fontSize: "1.1rem", fontWeight: 700, color: T.neg }}>₹{inst.emi.toLocaleString()}<span style={{ fontSize: "0.65rem", color: T.textMuted, fontWeight: 400 }}>/mo</span></div>}
                    <div style={{ fontSize: "0.72rem", color: T.textMuted, marginTop: 2 }}>₹{inst.paid.toLocaleString()} / ₹{inst.total.toLocaleString()}</div>
                  </div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <div style={{ flex: 1, height: 6, borderRadius: 3, background: isLight ? "rgba(0,0,0,0.08)" : "rgba(255,255,255,0.08)" }}>
                    <div style={{ height: "100%", borderRadius: 3, width: `${pct}%`, background: inst.color, transition: "width 1s ease", boxShadow: `0 0 8px ${inst.color}50` }} />
                  </div>
                  <div style={{ fontSize: "0.72rem", fontWeight: 700, color: inst.color, minWidth: 32 }}>{pct}%</div>
                </div>
              </div>
              <div style={{ display: "flex", gap: 6 }}>
                <button style={{ width: 32, height: 32, borderRadius: 10, border: `1px solid ${T.border}`, background: "transparent", color: T.textMuted, cursor: "pointer", fontSize: "0.8rem", transition: "all 0.2s" }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = T.accent; e.currentTarget.style.color = T.accent }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = T.border; e.currentTarget.style.color = T.textMuted }}>✏️</button>
                <button style={{ width: 32, height: 32, borderRadius: 10, border: `1px solid ${T.border}`, background: "transparent", color: T.textMuted, cursor: "pointer", fontSize: "0.8rem", transition: "all 0.2s" }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = T.neg; e.currentTarget.style.color = T.neg }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = T.border; e.currentTarget.style.color = T.textMuted }}>🗑️</button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

// ── SETTINGS PAGE ─────────────────────────────────────────────
const SettingsPage = ({ T, isLight, theme, setTheme }) => {
  const [notif, setNotif] = useState(true);
  const [autoSync, setAutoSync] = useState(true);
  const [currency, setCurrency] = useState("INR");
  const [saved, setSaved] = useState(false);

  const handleSave = () => {
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  const Toggle = ({ val, onChange }) => (
    <div onClick={() => onChange(!val)} style={{
      width: 44, height: 24, borderRadius: 12,
      background: val ? T.accent : isLight ? "rgba(0,0,0,0.15)" : "rgba(255,255,255,0.12)",
      position: "relative", cursor: "pointer", transition: "all 0.3s ease",
      boxShadow: val ? `0 0 12px ${T.accent}60` : "none",
    }}>
      <div style={{
        width: 18, height: 18, borderRadius: "50%", background: "#fff",
        position: "absolute", top: 3, left: val ? 22 : 3,
        transition: "left 0.3s cubic-bezier(0.34,1.56,0.64,1)",
        boxShadow: "0 2px 6px rgba(0,0,0,0.25)",
      }} />
    </div>
  );

  return (
    <div style={{ padding: "100px 28px 40px", maxWidth: 800, margin: "0 auto" }}>
      <div style={{ marginBottom: 36 }}>
        <div style={{ fontSize: "0.75rem", color: T.accent, fontWeight: 700, letterSpacing: 3, textTransform: "uppercase", marginBottom: 8 }}>Personalization</div>
        <h1 style={{ fontFamily: "'Playfair Display',serif", fontSize: "clamp(1.8rem,3vw,2.6rem)", fontWeight: 900, color: T.text }}>
          Control <span style={{ background: `linear-gradient(90deg,${T.accent},${T.accent2 || T.accent})`, WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent", backgroundClip: "text" }}>Panel</span>
        </h1>
        <p style={{ color: T.textMuted, marginTop: 6, fontSize: "0.9rem" }}>Customize your Paise Bachaaoo experience</p>
      </div>

      {/* Theme Selector */}
      <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 20, padding: "28px", marginBottom: 16, boxShadow: isLight ? "0 4px 20px rgba(0,0,0,0.06)" : "none" }}>
        <div style={{ fontFamily: "'Playfair Display',serif", fontSize: "1.1rem", fontWeight: 700, color: T.text, marginBottom: 4 }}>Theme Editor</div>
        <div style={{ fontSize: "0.78rem", color: T.textMuted, marginBottom: 20 }}>Choose your command center aesthetic</div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(5,1fr)", gap: 12 }}>
          {Object.values(THEMES).map(t => (
            <div key={t.id} onClick={() => setTheme(t)}
              style={{
                borderRadius: 16, padding: "16px 12px", textAlign: "center", cursor: "pointer",
                border: theme.id === t.id ? `2px solid ${t.accent}` : `1px solid ${T.border}`,
                background: theme.id === t.id ? `${t.accent}12` : isLight ? "rgba(0,0,0,0.03)" : "rgba(255,255,255,0.03)",
                transition: "all 0.3s cubic-bezier(0.34,1.56,0.64,1)",
                transform: theme.id === t.id ? "scale(1.05)" : "scale(1)",
                boxShadow: theme.id === t.id ? `0 8px 24px ${t.accent}30` : "none",
              }}>
              <div style={{ width: 36, height: 36, borderRadius: "50%", background: `linear-gradient(135deg,${t.orb1},${t.orb2})`, margin: "0 auto 10px", boxShadow: `0 4px 12px ${t.accent}50` }} />
              <div style={{ fontSize: "0.8rem", fontWeight: 700, color: T.text }}>{t.label}</div>
              {theme.id === t.id && <div style={{ fontSize: "0.65rem", color: T.accent, marginTop: 3 }}>✓ Active</div>}
            </div>
          ))}
        </div>
      </div>

      {/* Profile */}
      <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 20, padding: "28px", marginBottom: 16, boxShadow: isLight ? "0 4px 20px rgba(0,0,0,0.06)" : "none" }}>
        <div style={{ fontFamily: "'Playfair Display',serif", fontSize: "1.1rem", fontWeight: 700, color: T.text, marginBottom: 20 }}>Profile</div>
        <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 24 }}>
          <div style={{ width: 60, height: 60, borderRadius: "50%", background: `linear-gradient(135deg,${T.accent},${T.orb2 || T.accent})`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: "1.5rem", border: `3px solid ${T.border}` }}>S</div>
          <div>
            <div style={{ fontWeight: 700, color: T.text, fontSize: "1rem" }}>Sanmaya</div>
            <div style={{ fontSize: "0.78rem", color: T.textMuted }}>sanmaya@example.com · Premium Plan</div>
          </div>
          <button style={{ marginLeft: "auto", padding: "8px 18px", borderRadius: 20, border: `1px solid ${T.border}`, background: "transparent", color: T.accent, fontWeight: 600, fontSize: "0.78rem", cursor: "pointer", fontFamily: "'DM Sans',sans-serif" }}>Edit Profile</button>
        </div>
        {[
          { l: "Full Name", v: "Sanmaya", type: "text" },
          { l: "Email Address", v: "sanmaya@example.com", type: "email" },
          { l: "Monthly Budget Limit (₹)", v: "19000", type: "number" },
        ].map(f => (
          <div key={f.l} style={{ marginBottom: 14 }}>
            <div style={{ fontSize: "0.72rem", color: T.textMuted, fontWeight: 700, textTransform: "uppercase", letterSpacing: 1, marginBottom: 6 }}>{f.l}</div>
            <input defaultValue={f.v} type={f.type}
              style={{ width: "100%", background: isLight ? "rgba(0,0,0,0.04)" : "rgba(255,255,255,0.05)", border: `1.5px solid ${T.border}`, borderRadius: 12, padding: "12px 16px", color: T.text, fontSize: "0.9rem", fontFamily: "'DM Sans',sans-serif", outline: "none" }} />
          </div>
        ))}
      </div>

      {/* Preferences */}
      <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 20, padding: "28px", marginBottom: 16, boxShadow: isLight ? "0 4px 20px rgba(0,0,0,0.06)" : "none" }}>
        <div style={{ fontFamily: "'Playfair Display',serif", fontSize: "1.1rem", fontWeight: 700, color: T.text, marginBottom: 20 }}>Preferences</div>
        {[
          { l: "Push Notifications", d: "Get alerts for EMI due dates & budgets", val: notif, fn: setNotif },
          { l: "Auto Sync to Cloud", d: "Real-time Firestore sync across devices", val: autoSync, fn: setAutoSync },
        ].map(p => (
          <div key={p.l} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "14px 0", borderBottom: `1px solid ${T.border}` }}>
            <div>
              <div style={{ fontSize: "0.88rem", fontWeight: 600, color: T.text }}>{p.l}</div>
              <div style={{ fontSize: "0.75rem", color: T.textMuted, marginTop: 3 }}>{p.d}</div>
            </div>
            <Toggle val={p.val} onChange={p.fn} />
          </div>
        ))}
        <div style={{ padding: "14px 0" }}>
          <div style={{ fontSize: "0.72rem", color: T.textMuted, fontWeight: 700, textTransform: "uppercase", letterSpacing: 1, marginBottom: 8 }}>Default Currency</div>
          <div style={{ display: "flex", gap: 8 }}>
            {["INR", "USD", "EUR", "GBP"].map(c => (
              <button key={c} onClick={() => setCurrency(c)} style={{
                padding: "8px 16px", borderRadius: 20, border: `1px solid ${currency === c ? T.accent : T.border}`,
                background: currency === c ? `${T.accent}18` : "transparent",
                color: currency === c ? T.accent : T.textMuted, fontWeight: 700, fontSize: "0.8rem",
                cursor: "pointer", fontFamily: "'DM Sans',sans-serif", transition: "all 0.2s",
              }}>{c}</button>
            ))}
          </div>
        </div>
      </div>

      {/* Danger + Save */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}>
        <button style={{ padding: "12px 24px", borderRadius: 14, border: `1px solid ${T.neg}50`, background: `${T.neg}12`, color: T.neg, fontWeight: 700, fontSize: "0.88rem", cursor: "pointer", fontFamily: "'DM Sans',sans-serif", transition: "all 0.2s" }}>
          🚪 Sign Out
        </button>
        <button onClick={handleSave} style={{
          padding: "12px 32px", borderRadius: 14, border: "none", cursor: "pointer",
          background: saved ? T.pos : `linear-gradient(135deg,${T.accent},${T.orb1 || T.accent})`,
          color: isLight ? "#fff" : "#080612", fontWeight: 700, fontSize: "0.95rem",
          fontFamily: "'DM Sans',sans-serif", transition: "all 0.3s",
          boxShadow: `0 8px 24px ${T.accent}40`,
        }}>
          {saved ? "✓ Saved!" : "💾 Save Changes"}
        </button>
      </div>
    </div>
  );
};

// ── FLOATING ACTION BUTTON ────────────────────────────────────
const FAB = ({ T, onClick, isLight }) => {
  const [hover, setHover] = useState(false);
  return (
    <button
      onClick={onClick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        position: "fixed", bottom: 32, right: 32, zIndex: 90,
        width: 60, height: 60, borderRadius: "50%", border: "none",
        background: `linear-gradient(135deg,${T.accent},${T.orb1 || T.accent})`,
        color: isLight ? "#fff" : "#080612", fontSize: "1.5rem",
        cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center",
        boxShadow: `0 8px 32px ${T.accent}50`,
        transform: hover ? "scale(1.12) rotate(45deg)" : "scale(1) rotate(0deg)",
        transition: "all 0.3s cubic-bezier(0.34,1.56,0.64,1)",
      }}>
      +
      {hover && (
        <div style={{ position: "absolute", right: 70, background: T.card, border: `1px solid ${T.border}`, borderRadius: 10, padding: "6px 14px", whiteSpace: "nowrap", fontSize: "0.78rem", fontWeight: 700, color: T.text, fontFamily: "'DM Sans',sans-serif" }}>
          Add Transaction
        </div>
      )}
    </button>
  );
};

// ── ROOT APP ──────────────────────────────────────────────────
export default function App() {
  const [theme, setTheme] = useState(THEMES.dark);
  const [activePage, setActivePage] = useState("Dashboard");
  const [showModal, setShowModal] = useState(false);
  const T = theme;
  const isLight = T.id === "cloud";

  const renderPage = () => {
    switch (activePage) {
      case "Dashboard": return <DashboardPage T={T} onOpenModal={() => setShowModal(true)} isLight={isLight} />;
      case "Market": return <MarketPage T={T} isLight={isLight} />;
      case "Analytics": return <AnalyticsPage T={T} isLight={isLight} />;
      case "Installments": return <InstallmentsPage T={T} isLight={isLight} />;
      case "Settings": return <SettingsPage T={T} isLight={isLight} theme={theme} setTheme={setTheme} />;
      default: return <DashboardPage T={T} onOpenModal={() => setShowModal(true)} isLight={isLight} />;
    }
  };

  return (
    <div style={{ minHeight: "100vh", background: T.bg, fontFamily: "'DM Sans',sans-serif", transition: "background 0.5s ease", position: "relative" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700;900&family=DM+Sans:wght@300;400;500;600;700&display=swap');
        *, *::before, *::after { box-sizing:border-box; margin:0; padding:0; }
        ::-webkit-scrollbar { width:4px; }
        ::-webkit-scrollbar-thumb { background:${T.accent}; border-radius:2px; }
        @keyframes fadeInUp { from{opacity:0;transform:translateY(24px)} to{opacity:1;transform:translateY(0)} }
        @keyframes fadeIn   { from{opacity:0} to{opacity:1} }
        @keyframes pulse-ring { 0%{transform:scale(1);opacity:0.8} 100%{transform:scale(1.8);opacity:0} }
        .card-hover { transition:all 0.3s cubic-bezier(0.34,1.2,0.64,1) !important; }
        .card-hover:hover { transform:translateY(-4px) !important; }
      `}</style>

      {/* Ambient Orbs */}
      <div style={{ position: "fixed", width: 600, height: 600, borderRadius: "50%", background: T.orb1, filter: "blur(120px)", opacity: 0.07, top: -200, left: -200, pointerEvents: "none", transition: "background 0.5s", zIndex: 0 }} />
      <div style={{ position: "fixed", width: 500, height: 500, borderRadius: "50%", background: T.orb2, filter: "blur(120px)", opacity: 0.07, bottom: -150, right: -150, pointerEvents: "none", transition: "background 0.5s", zIndex: 0 }} />
      <div style={{ position: "fixed", inset: 0, backgroundImage: `radial-gradient(circle at 1px 1px, ${T.accent}08 1px, transparent 0)`, backgroundSize: "40px 40px", pointerEvents: "none", zIndex: 0 }} />

      <Navbar T={T} activePage={activePage} setActivePage={setActivePage} theme={theme} setTheme={setTheme} isLight={isLight} />

      <main style={{ position: "relative", zIndex: 1 }}>
        {renderPage()}
      </main>

      <div style={{ position: "relative", zIndex: 1 }}>
        <Footer T={T} isLight={isLight} />
      </div>

      {activePage !== "Settings" && (
        <FAB T={T} isLight={isLight} onClick={() => setShowModal(true)} />
      )}

      {showModal && (
        <TransactionModal T={T} isLight={isLight} onClose={() => setShowModal(false)} />
      )}
    </div>
  );
}

